--
-- Table structure for table `lastnames`
--

CREATE TABLE `lastnames` (
    `Name` varchar(128) NOT NULL,
    `Name ASCII` varchar(128) NOT NULL,
    `Country code` varchar(128) NOT NULL,
    `Country name` varchar(128) NOT NULL,
    `Continent` varchar(128) NOT NULL,
    `Official` varchar(128) NOT NULL,
    `Gender` varchar(128) NOT NULL,
    `Country Rank` varchar(128) NOT NULL,
    `Frequency` varchar(128) NOT NULL,
    `Frequency source` varchar(128) NOT NULL,
    `Quality` varchar(128) NOT NULL,
    `Script` varchar(128) NOT NULL,
    `Cumulative percentage` varchar(128) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

